(()=>{const scope=document.querySelector('[data-dismiss-scope]');const rail=scope.nextElementSibling;
const T=k=>{const q=s=>k.matches(s)||k.querySelector(s);return q('[data-home-tables]')?'tables':q('[data-head-holder]')?'holder':q('section[aria-label="Not sure where to go?"]')?'panel':q('[data-whats-new]')?'news':q('[data-lead-story]')?'lead':q('[data-welcome-strip]')?'welcome':(k.textContent.includes('Pick up where')?'decks':(k.textContent.includes('Commitments')?'commit':(k.textContent.includes('Friends')?'friends':'other')))};
const all=[...scope.children,...(rail?rail.children:[])];const by={};all.forEach(k=>{by[T(k)]=k});
const ORDER=["tables", "panel", "lead", "news", "decks", "friends", "commit"]; ORDER.forEach((n,i)=>{if(by[n])by[n].style.order=String(i)});
const desk=innerWidth>=1180; if(desk&&by.commit&&by.friends){by.commit.style.order='0';by.friends.style.order='1'}  if(desk){const n=by.news;rail.prepend(n);n.setAttribute('data-rail-news','');n.style.order='';n.classList.remove('order-3');n.style.marginBottom='10px';const a=n.querySelector('h2 a');const f=[...n.querySelectorAll('button')].find(b=>b.textContent.trim()==='Clear all');if(a&&f){const r=f.parentElement;r.style.display='flex';r.style.justifyContent='space-between';r.style.alignItems='center';a.style.marginLeft='14px';r.prepend(a)}} })()

